import Horizon, { useState, useEffect, forwardRef } from '@cloudsop/horizon';

// input组件的value如果是reactive包裹，在中间位置输入后会导致光标移动到末尾，该组件可以规避这个问题
export const ReactiveAdapterInput = forwardRef(({ value, onChange, ...props }, ref) => {
  const [val, setVal] = useState(props.value);

  useEffect(() => {
    if (value !== undefined && value !== val) {
      setVal(value);
    }
  }, [value]);

  const changeHandler = e => {
    const newVal = e.target.value;
    setVal(newVal);
    if (onChange) {
      onChange(e);
    }
  };

  return <input value={val} onChange={changeHandler} {...props} ref={ref} />;
});
